PRAGMA foreign_keys=ON;
CREATE TABLE products(product_id TEXT PRIMARY KEY,product_name TEXT NOT NULL UNIQUE,min_temperature REAL NOT NULL,max_temperature REAL NOT NULL,temperature_unit TEXT NOT NULL DEFAULT 'C' CHECK(temperature_unit='C'),CHECK(min_temperature<=max_temperature));
CREATE TABLE lots(lot_id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(product_id),manufacture_date TEXT NOT NULL,expiry_date TEXT NOT NULL,CHECK(date(manufacture_date)<date(expiry_date)));
CREATE TABLE shipments(shipment_id TEXT PRIMARY KEY,lot_id TEXT NOT NULL REFERENCES lots(lot_id),shipment_status TEXT NOT NULL CHECK(shipment_status IN('PLANNED','IN_TRANSIT','DELIVERED','ON_HOLD','CANCELLED')),origin TEXT NOT NULL,destination TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT,CHECK(end_time IS NULL OR datetime(end_time)>=datetime(start_time)));
CREATE TABLE packaging(packaging_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),packaging_type TEXT NOT NULL CHECK(packaging_type IN('INSULATED_BOX','REFRIGERATED_CONTAINER','THERMAL_BAG')),insulation_profile TEXT NOT NULL,validated_min_hours INTEGER NOT NULL CHECK(validated_min_hours>0));
CREATE TABLE loggers(logger_id TEXT PRIMARY KEY,logger_status TEXT NOT NULL CHECK(logger_status IN('ACTIVE','MAINTENANCE','RETIRED')),calibration_date TEXT NOT NULL,calibration_due_date TEXT NOT NULL,calibration_uncertainty_c REAL NOT NULL CHECK(calibration_uncertainty_c>=0),CHECK(date(calibration_due_date)>=date(calibration_date)));
CREATE TABLE logger_assignments(assignment_id TEXT PRIMARY KEY,logger_id TEXT NOT NULL REFERENCES loggers(logger_id),shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),assignment_sequence INTEGER NOT NULL,assigned_at TEXT NOT NULL,unassigned_at TEXT,UNIQUE(shipment_id,assignment_sequence),CHECK(unassigned_at IS NULL OR datetime(unassigned_at)>datetime(assigned_at)));
CREATE INDEX idx_assignment_logger_dates ON logger_assignments(logger_id,assigned_at,unassigned_at);
CREATE TABLE temperature_readings(reading_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),logger_id TEXT NOT NULL REFERENCES loggers(logger_id),reading_time TEXT NOT NULL,temperature REAL NOT NULL,UNIQUE(logger_id,reading_time));
CREATE INDEX idx_reading_shipment_time ON temperature_readings(shipment_id,reading_time);
CREATE TABLE custody_events(event_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),event_time TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN('PICKUP','HANDOFF','DELIVERY','EXCEPTION')),responsible_party TEXT NOT NULL,from_party TEXT,to_party TEXT);
CREATE INDEX idx_custody_shipment_time ON custody_events(shipment_id,event_time);
CREATE TABLE route_stops(stop_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),stop_sequence INTEGER NOT NULL,stop_location TEXT NOT NULL,arrival_time TEXT NOT NULL,departure_time TEXT,dwell_minutes INTEGER NOT NULL CHECK(dwell_minutes>=0),UNIQUE(shipment_id,stop_sequence),CHECK(departure_time IS NULL OR datetime(departure_time)>=datetime(arrival_time)));
CREATE TABLE threshold_policies(policy_id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(product_id),min_temperature REAL NOT NULL,max_temperature REAL NOT NULL,allowed_duration_minutes INTEGER NOT NULL CHECK(allowed_duration_minutes>=0),effective_from TEXT NOT NULL,effective_to TEXT,CHECK(min_temperature<=max_temperature),CHECK(effective_to IS NULL OR datetime(effective_to)>datetime(effective_from)));
CREATE INDEX idx_policy_product_dates ON threshold_policies(product_id,effective_from,effective_to);
CREATE TABLE excursion_reports(report_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),policy_id TEXT NOT NULL REFERENCES threshold_policies(policy_id),start_time TEXT NOT NULL,end_time TEXT NOT NULL,excursion_duration_minutes INTEGER NOT NULL CHECK(excursion_duration_minutes>0),severity TEXT NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),first_reading_id TEXT NOT NULL REFERENCES temperature_readings(reading_id),last_reading_id TEXT NOT NULL REFERENCES temperature_readings(reading_id),decision TEXT NOT NULL CHECK(decision IN('WITHIN_ALLOWANCE','NON_COMPLIANT')),CHECK(datetime(end_time)>=datetime(start_time)));
CREATE TABLE shipment_status_history(history_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),old_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('PLANNED','IN_TRANSIT','DELIVERED','ON_HOLD','CANCELLED')),changed_at TEXT NOT NULL,changed_by TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE anomaly_issues(issue_id TEXT PRIMARY KEY,issue_type TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,shipment_id TEXT REFERENCES shipments(shipment_id),expected_value TEXT,actual_value TEXT,expected_decision TEXT NOT NULL,description TEXT NOT NULL,injected INTEGER NOT NULL DEFAULT 1 CHECK(injected IN(0,1)));
CREATE TABLE compliance_reports(compliance_id TEXT PRIMARY KEY,shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id),policy_id TEXT NOT NULL REFERENCES threshold_policies(policy_id),decision TEXT NOT NULL CHECK(decision IN('COMPLIANT','NON_COMPLIANT','INSUFFICIENT_DATA','ON_HOLD')),reading_count INTEGER NOT NULL,gap_count INTEGER NOT NULL,excursion_count INTEGER NOT NULL,route_dwell_violation_count INTEGER NOT NULL,custody_complete INTEGER NOT NULL CHECK(custody_complete IN(0,1)),generated_at TEXT NOT NULL,rationale TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reading_assignment_check ON temperature_readings(shipment_id,logger_id,reading_time);
